import{_ as r,l as i,o as e,c as n,v as t,p as l,x as s,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"指令调度","description":"","frontmatter":{"title":"指令调度","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/instruction-sched.md","filePath":"cs/instruction-sched.md","lastUpdated":1789023840000}'),h={name:"cs/instruction-sched.md"};function u(_,a,f,A,m,E){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="指令调度" tabindex="-1">指令调度 <a class="header-anchor" href="#指令调度" aria-label="Permalink to &quot;指令调度&quot;">​</a></h1><div class="epigraph"><p>数据相关与延迟槽决定指令不能任意换序；表调度在基本块内按就绪队列选下一条，缩短占用周期，不改语义。</p><footer>—— 据 Hennessy and Gross, Postpass Code Optimization of Pipeline Constraints, 1983；龙书第 8 章；组成课流水线整理</footer></div><p>上一课<a href="/cs/instruction-select">指令选择</a>交出带虚拟寄存器的机器指令，并声明不排流水线。组成课已有<a href="/cs/data-hazard-forward">数据冒险</a>与<a href="/cs/pipeline-five-stage">五级流水</a>。本课不重选 opcode。缺口是<strong>块内换序</strong>：load 的延迟、乘的延迟、真相关 \\(x\\) 写后读，把指令排成就绪表。寄存器分配尚未发生，调度可与分配交错；主干先调度再着色，或承认二者互相影响。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>选择后的序列合法，但相邻 <code>lw</code> 与用其结果的 <code>add</code> 会停顿。表调度：节点是指令，边是真/反/输出相关，权是延迟。就绪队列里挑使关键路径不拉长的指令发射。缺口是这份 DAG 调度，不是再做转发硬件。</p><p>反相关与输出相关在虚拟寄存器无限时可靠改名削弱；真相关不能消。分配之后物理寄存器会再引入相关，可能要再调度或保守留空。本课以虚拟名上的表调度为对象。</p><h3 id="调度不是超标量发射" tabindex="-1">调度不是超标量发射 <a class="header-anchor" href="#调度不是超标量发射" aria-label="Permalink to &quot;调度不是超标量发射&quot;">​</a></h3><p>超标量硬件同时发多条；本课是编译器静态排单发射或静态 VLIW 槽。组成课的<a href="/cs/superscalar-issue">多发射</a>是硬件；本课不代替 Tomasulo。</p><p><span class="marginnote">Hennessy–Gross 1983 流水约束后处理。龙书 8.10 节指令调度。Appel 有短章。本课块内；跨块（追踪调度）点名不写。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建依赖 DAG。拓扑就绪：入度为零。循环：选优先（高度、延迟加权），更新子节点。插 nop 或让硬件停顿——视目标是否暴露延迟槽（经典 MIPS）而定。RISC-V 常靠硬件互锁，调度仍减停顿。</p>',11)),(e(),l(p,null,{default:s(()=>[c(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MI%5B%22%E9%80%89%E5%AE%9A%E7%9A%84%E6%9C%BA%E5%99%A8%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20DEP%5B%22%E7%9B%B8%E5%85%B3%20DAG%22%5D%0A%20%20DEP%20--%3E%20LIST%5B%22%E8%A1%A8%E8%B0%83%E5%BA%A6%22%5D%0A%20%20LIST%20--%3E%20SEQ%5B%22%E6%96%B0%E5%BA%8F%20%2B%20%E5%A1%AB%E5%BB%B6%E8%BF%9F%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><a href="/cs/loop-invariant">循环不变式</a> 外提是另一遍，可在调度前把不变 load 提出块。本课块内不保证最优：表调度是启发式，最优调度难。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>正确性：尊重真相关与内存别名（保守：可能别名则当相关）。volatile 与调用是屏障。不要调度过可能抛的指令而不顾异常顺序——精确异常要求可见状态；本课整数运算默认可动，访存保守。</p><p>与着色：调度拉长同时活区间，冲突图变密，可能多溢出。这是交错的来源，下一课溢出再处理。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不着色、不写窥孔代数。不做软件流水满堂。后课默认：块内指令序已考虑延迟。冲突图着色把虚拟收成物理或 spill。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>表调度按相关 DAG 与延迟排块内序。</li><li>真相关不能改名消掉；别名保守当边。</li><li>可能加长活跃区间，留给分配。</li><li>出处：Hennessy and Gross, 1983；龙书第 8 章。</li></ul>',8))])}const T=r(h,[["render",u]]);export{P as __pageData,T as default};
